		t.Fatal(err)
	}
	if credentials.calls != 1 || keys.calls != 1 {
		t.Fatal("backup owner did not fetch both exact Vault versions")
	}
	for _, item := range []struct {
		name, digest string
		maximum      int64
		want         []byte
