	a := &Agent{cfg: AgentConfig{Cell: r.Cell, Node: r.Node, Environment: r.Environment, Identity: key, NATSUserPublicKey: r.NATSUserPublicKey}, session: session{RegistrationGeneration: r.Generation}}
