	}
	if err := verifyRequest(req, key.Public().(ed25519.PublicKey), "gru", time.Now().UTC()); err != nil {
		t.Fatalf("verify signed host request: %v", err)
	}
	wire, err := protocol.EncodeJSON(req.Envelope)
	if err != nil {
		t.Fatal(err)
	}
