func readManagedClientMaterial(material, digest, sqlBundleDigest, replicationListenAddress string,
	identity WorkloadIdentity, ownerUID uint32,
) ([]string, error) {
	manifestPath := filepath.Join(material, managedClientManifestName)
	manifestBytes, err := readManagedClientFile(manifestPath, digest, identity, 4<<10, ownerUID)
	if err != nil {
		return nil, err
	}
	var manifest managedClientManifest
	if err := json.Unmarshal(manifestBytes, &manifest, json.RejectUnknownMembers(true)); err != nil ||
		manifest.Version != 1 || !lowerHex(manifest.ClientConfigSHA256, 64) ||
		!lowerHex(manifest.CertificateChainSHA256, 64) || !lowerHex(manifest.PrivateKeySHA256, 64) ||
		!lowerHex(manifest.APIKeyRegistrySHA256, 64) {
		return nil, errors.New("managed client material manifest is invalid")
	}
	configPath := filepath.Join(material, managedClientConfigName)
	configBytes, err := readManagedClientFile(configPath, manifest.ClientConfigSHA256, identity, 16<<10, ownerUID)
	if err != nil {
		return nil, err
	}
	var config managedClientConfig
	if err := json.Unmarshal(configBytes, &config, json.RejectUnknownMembers(true)); err != nil || config.Version != 1 ||
		config.CertificateChain != filepath.Join(material, managedClientChainName) ||
		config.PrivateKey != filepath.Join(material, managedClientKeyName) ||
		config.APIKeyRegistry != filepath.Join(material, managedClientRegistryName) ||
		config.HandshakeTimeoutMS != 0 && (config.HandshakeTimeoutMS < 1000 || config.HandshakeTimeoutMS > 10000) {
		return nil, errors.New("managed client config does not bind deterministic material paths")
	}
	if sqlBundleDigest == "" {
		if config.SQLListenAddress != "" {
			return nil, errors.New("SQL listener is configured without a signed schema bundle pin")
		}
	} else if !lowerHex(sqlBundleDigest, 64) ||
		!validPrivateSQLSocket(config.SQLListenAddress, config.ListenAddress, replicationListenAddress) {
		return nil, errors.New("managed SQL listener is not a private, distinct TLS socket")
	}
	address := config.ListenAddress
	if address == "" {
		address = "127.0.0.1:9465"
	}
	listen, err := netip.ParseAddrPort(address)
	if err != nil || listen.String() != address || listen.Port() == 0 || !listen.Addr().Is4() ||
		!listen.Addr().IsLoopback() && !listen.Addr().IsPrivate() {
		return nil, errors.New("managed client listener must be an IPv4 loopback or private address and port")
	}
	for _, file := range []struct {
		name, digest string
		maximum      int64
	}{
		{managedClientChainName, manifest.CertificateChainSHA256, 2 << 20},
		{managedClientKeyName, manifest.PrivateKeySHA256, 2 << 20},
		{managedClientRegistryName, manifest.APIKeyRegistrySHA256, 256 << 10},
	} {
		contents, err := readManagedClientFile(filepath.Join(material, file.name), file.digest, identity, file.maximum, ownerUID)
		if err != nil {
			return nil, err
		}
		clear(contents)
	}
	if sqlBundleDigest != "" {
		contents, err := readManagedClientFile(filepath.Join(material, sqlSchemaBundleName),
			sqlBundleDigest, identity, managedSQLSchemaBundleMaxBytes, ownerUID)
		if err != nil {
			return nil, fmt.Errorf("managed SQL schema bundle: %w", err)
		}
		clear(contents)
	}
	args := []string{
		"--client-config", configPath,
		"--client-managed-material-manifest", manifestPath,
		"--client-managed-material-manifest-sha256", digest,
	}
	if sqlBundleDigest != "" {
		args = append(args, "--sql-schema-bundle", filepath.Join(material, sqlSchemaBundleName))
	}
	if !listen.Addr().IsLoopback() {
		args = append(args, "--client-allow-nonloopback")
	}
	return args, nil
}

func validPrivateSQLSocket(address, httpsAddress, replicationAddress string) bool {
	if !validPrivateSQLAddress(address) {
		return false
	}
	_, port, ok := socketPort(address)
	_, httpsPort, httpsOK := socketPort(httpsAddress)
	_, replicationPort, replicationOK := socketPort(replicationAddress)
	if !ok || !httpsOK || !replicationOK || port == httpsPort || port == replicationPort {
		return false
	}
	return true
}

func socketPort(address string) (string, int, bool) {
	host, port, err := net.SplitHostPort(address)
	ip := net.ParseIP(host)
	portNumber, portErr := strconv.Atoi(port)
	if err != nil || ip == nil || portErr != nil || portNumber < 1 || portNumber > 65535 {
		return "", 0, false
	}
	return host, portNumber, true
}

func validPrivateSQLAddress(address string) bool {
	host, _, ok := socketPort(address)
	if !ok {
		return false
	}
	ip := net.ParseIP(host)
	return ip != nil && ip.IsPrivate() && !ip.IsLoopback() && !ip.IsUnspecified()
}

install_file.text:
func installManagedFile(directory, name string, contents []byte, digest string, identity WorkloadIdentity) error {
	allowed := slices.Contains(managedHostFileNames[:], name) ||
		name == backupCredentialFileName || name == backupDataKeyFileName
	if !allowed || len(contents) == 0 ||
		len(contents) > managedHostFileLimit(name) {
		return errors.New("invalid managed material installation")
	}
	sum := sha256.Sum256(contents)
	if hex.EncodeToString(sum[:]) != digest {
		return errors.New("managed material install digest mismatch")
	}
	target := filepath.Join(directory, name)
	if _, err := os.Lstat(target); err == nil {
		_, err = verifyManagedMaterial(target, digest, identity, int64(managedHostFileLimit(name)))
		return err
	} else if !errors.Is(err, os.ErrNotExist) {
		return err
	}
	dirFD, err := unix.Open(directory, unix.O_RDONLY|unix.O_DIRECTORY|unix.O_NOFOLLOW|unix.O_CLOEXEC, 0)
	if err != nil {
		return err
	}
	defer unix.Close(dirFD)
	token, err := randomID()
	if err != nil {
		return err
	}
	temporary := "." + name + "." + token
	fileFD, err := unix.Openat(dirFD, temporary, unix.O_WRONLY|unix.O_CREAT|unix.O_EXCL|unix.O_NOFOLLOW|unix.O_CLOEXEC, 0440)
	if err != nil {
		return err
	}
	defer unix.Unlinkat(dirFD, temporary, 0)
	file := os.NewFile(uintptr(fileFD), temporary)
	if err := unix.Fchown(fileFD, 0, int(identity.GID)); err != nil {
		file.Close()
		return err
	}
	if err := file.Chmod(0440); err != nil {
		file.Close()
		return err
	}
	if _, err := io.Copy(file, bytes.NewReader(contents)); err != nil {
		file.Close()
		return err
	}
	if err := file.Sync(); err != nil {
		file.Close()
		return err
	}
	if err := file.Close(); err != nil {
		return err
	}
	if err := unix.Renameat2(dirFD, temporary, dirFD, name, unix.RENAME_NOREPLACE); err != nil {
		if errors.Is(err, unix.EEXIST) {
			_, err = verifyManagedMaterial(target, digest, identity, int64(managedHostFileLimit(name)))
		}
		return err
	}
	return unix.Fsync(dirFD)
}

verify_material.text:
func verifyManagedMaterial(path, digest string, identity WorkloadIdentity, maximum int64) ([]byte, error) {
	info, err := os.Lstat(path)
	if err != nil {
		return nil, err
	}
	owner, ok := info.Sys().(*syscall.Stat_t)
	if !ok || !info.Mode().IsRegular() || info.Mode()&os.ModeSymlink != 0 || owner.Uid != 0 || owner.Gid != identity.GID ||
		info.Mode().Perm() != 0440 || info.Size() < 1 || info.Size() > maximum {
		return nil, fmt.Errorf("unsafe managed runtime material %s", path)
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	check, err := os.Lstat(path)
	if err != nil || !os.SameFile(info, check) || int64(len(data)) != info.Size() {
		return nil, fmt.Errorf("managed runtime material changed while reading %s", path)
	}
	sum := sha256.Sum256(data)
	if hex.EncodeToString(sum[:]) != digest {
		return nil, fmt.Errorf("managed runtime material digest mismatch for %s", path)
	}
	return data, nil
}

