agent_request.text:
func (a *Agent) request(ctx context.Context, operation string, payload, out any) error {
	_, err := a.sendToLeader(ctx, operation, payload, out, nil, nil)
	return err
}

agent_send.text:
func (a *Agent) sendToLeader(ctx context.Context, operation string, payload, out any,
	signedOut *protocol.Envelope, prepare func(*request) error,
) (request, error) {
	for attempt := 1; ; attempt++ {
		r, err := a.makeRequest(operation, payload)
		if err != nil {
			return request{}, err
		}
		if prepare != nil {
			if err := prepare(&r); err != nil {
				return request{}, err
			}
		}
		err = exchangeWithEnvelope(ctx, a.cfg.Conn, a.cfg.Cell, a.cfg.ControllerPublicKey, r, out, signedOut)
		if !errors.Is(err, errControllerNotLeader) || attempt == leaderRequestAttempts {
			return r, err
		}
		select {
		case <-ctx.Done():
			return request{}, ctx.Err()
		case <-time.After(time.Duration(attempt) * leaderRetryBackoff):
		}
	}
}

wire_exchange.text:
func exchangeWithEnvelope(ctx context.Context, conn *nats.Conn, cell string, controllerKey ed25519.PublicKey,
	r request, out any, signedOut *protocol.Envelope,
) error {
	if conn == nil {
		return errors.New("NATS connection is required")
	}
	data, err := protocol.EncodeJSON(r.Envelope)
	if err != nil {
		return err
	}
	if len(data) > 64<<10 {
		return errors.New("host request is too large")
	}
	subject, err := protocol.AgentObservationSubject(cell, r.NATSUserPublicKey, r.Operation)
	if err != nil {
		return err
	}
	timeout := 5 * time.Second
	if r.Operation == "material" || r.Operation == "function-material" || r.Operation == "volume-init" || r.Operation == "runtime-effect" || r.Operation == "container-material" || r.Operation == "registry-admission" {
		timeout = 30 * time.Second
	}
	deadline, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()
	msg, err := conn.RequestMsgWithContext(deadline, &nats.Msg{Subject: subject, Data: data, Header: observability.TraceHeader(ctx, nil)})
	if err != nil {
		return err
	}
	if len(msg.Data) > 512<<10 {
		return errors.New("host response is too large")
	}
	var signed protocol.Envelope
	if err := protocol.DecodeStrict(msg.Data, &signed, 512<<10); err != nil {
		return err
	}
	if err := protocol.VerifyEnvelope(signed, protocol.EnvelopeScope{Region: cell, Kind: "host.response." + r.Operation, Actor: "controller", OperationID: entityid.Derive("host-request", r.Nonce), Epoch: r.Epoch}, controllerKey, time.Now().UTC(), protocol.VerifyPolicy{MaxLifetime: requestTTL, ClockSkew: maxClockSkew}); err != nil {
		return err
	}
	var result response
	if err := decodeStrict([]byte(signed.Payload), &result); err != nil {
		return err
	}
	if result.Nonce != r.Nonce || result.Node != r.Node || result.SessionID != r.SessionID || result.Epoch != r.Epoch || result.Operation != r.Operation {
		return errors.New("host response binding mismatch")
	}
	if result.Error != "" {
		if strings.HasPrefix(result.Error, authority.ErrNotLeader.Error()) {
			return fmt.Errorf("%w: %s", errControllerNotLeader, result.Error)
		}
		if result.Retryable {
			if result.Error == errSessionContention.Error() {
				return errSessionContention
			}
			if r.Operation == "session" {
				return fmt.Errorf("%w: %s", errSessionBackendUnavailable, result.Error)
			}
			return errArtifactPreparing
		}
		if r.Operation == "session" {
			if result.Error == errSessionOwned.Error() {
				return errSessionOwned
			}
			return fmt.Errorf("%w: %s", errSessionRequestDenied, result.Error)
		}
		return fmt.Errorf("host request denied: %s", result.Error)
	}
	if out != nil {
		if err := decodeStrict(result.Payload, out); err != nil {
			return err
		}
	}
	if signedOut != nil {
		*signedOut = signed
	}
	return nil
}

report_validation.text:
func validateManagedReportForDesired(report Report, desired Desired) error {
	if desired.ManagedMember == nil {
		if report.Managed != nil {
			return errors.New("generic desired cannot accept a managed process report")
		}
		return nil
	}
	if report.State != "running" {
		if report.Managed != nil {
			return errors.New("nonrunning managed report cannot carry process proof")
		}
		return nil
	}
	launch, observation := desired.ManagedMember, report.Managed
	if launch.Runtime == nil || observation == nil || observation.Member != launch.Member ||
		observation.Authority != launch.Authority || observation.OCI != launch.OCI ||
		observation.VolumeID != launch.VolumeID || observation.AttachmentID != launch.AttachmentID ||
		observation.AttachmentETag != launch.AttachmentETag ||
		observation.FileSystemUUID != launch.Runtime.FileSystemUUID ||
		observation.FileSystemType != launch.Runtime.FileSystemType ||
		observation.MountDevice != launch.Runtime.DevicePath || observation.MountPath != launch.Runtime.MountPath ||
		observation.MountID == 0 || observation.ProcessPID < 2 || observation.ProcessStart == "" ||
		!strings.HasPrefix(observation.ProcessCgroup, "/") || !lowerHex(observation.ProcessBootID, 32) ||
		!observation.StorageRecovered || !observation.ListenerReady {
		return errors.New("managed report lacks exact mounted process identity")
	}
	if observation.Container != nil && (!observation.Container.valid() ||
		observation.Container.HostPID != observation.ProcessPID || observation.Container.KernelStart != observation.ProcessStart ||
		observation.Container.Cgroup != observation.ProcessCgroup || observation.Container.MountID != observation.MountID) {
		return errors.New("managed container report differs from its kernel identity")
	}
	if proof := observation.ServingProof; proof != nil {
		if proof.SchemaVersion != 1 || proof.Process.PID != managedReportMemberPID(observation) ||
			proof.Process.StartNonce != observation.ProcessBootID ||
			proof.Scope != (memberstatus.Scope{
				ClusterID: launch.Member.Scope.ClusterID, TenantID: launch.Member.Scope.TenantID,
				DatabaseID: launch.Member.Scope.DatabaseID, ShardID: launch.Member.Scope.ShardID,
				MemberID: launch.Member.Scope.MemberID, Incarnation: launch.Member.Scope.Incarnation,
			}) || proof.Authority != (memberstatus.Authority{
			Epoch: launch.Authority.Epoch, ConfigurationID: launch.Authority.ConfigurationID,
			CertificateSHA256: launch.Authority.CertificateSHA256, TLSLeafSHA256: launch.Authority.TLSLeafSHA256,
		}) || !proof.Serving || !proof.Listeners.Client || !proof.Listeners.Replication ||
			proof.Replication.PeerMemberID != launch.Runtime.ReplicationPeerMemberID {
			return errors.New("managed serving proof differs from the desired process or signed member")
		}
	}
	return nil
}

memory_contract.text:
func validateManagedHostMemoryAt(r Registration, meminfoPath, membershipPath, cgroupRoot string) error {
	meminfo, err := os.ReadFile(meminfoPath)
	if err != nil {
		return fmt.Errorf("read physical memory: %w", err)
	}
	membership, err := os.ReadFile(membershipPath)
	if err != nil {
		return fmt.Errorf("read memory cgroup membership: %w", err)
	}
	physical, err := physicalMemoryBytes(string(meminfo))
	if err != nil {
		return err
	}
	limit, err := ancestorMemoryLimit(cgroupRoot, string(membership))
	if err != nil {
		return err
	}
	available := min(physical, limit)
	reserve := uint64(r.SystemReserveBytes)
	if r.SystemReserveBytes <= 0 || r.Capacity.MemoryBytes <= 0 || reserve > available ||
		uint64(r.Capacity.MemoryBytes) > available-reserve {
		return errors.New("managed allocatable memory plus system reserve exceeds host limit")
	}
	return nil
}

func physicalMemoryBytes(data string) (uint64, error) {
	for line := range strings.SplitSeq(data, "\n") {
		value, ok := strings.CutPrefix(line, "MemTotal:")
		if !ok {
			continue
		}
		fields := strings.Fields(value)
		if len(fields) != 2 || fields[1] != "kB" {
			return 0, errors.New("invalid physical MemTotal")
		}
		kib, err := strconv.ParseUint(fields[0], 10, 64)
		if err != nil || kib == 0 || kib > math.MaxUint64/1024 {
			return 0, errors.New("invalid physical MemTotal")
		}
		return kib * 1024, nil
	}
	return 0, errors.New("physical MemTotal is absent")
}

func ancestorMemoryLimit(root, membership string) (uint64, error) {
	var relative string
	for line := range strings.SplitSeq(strings.TrimSpace(membership), "\n") {
		path, ok := strings.CutPrefix(line, "0::")
		if !ok {
			continue
		}
		if relative != "" || !filepath.IsAbs(path) || filepath.Clean(path) != path {
			return 0, errors.New("invalid unified memory cgroup membership")
		}
		relative = path
	}
	if relative == "" {
		return 0, errors.New("unified memory cgroup membership is absent")
	}
	if relative == "/" {
		return 0, errors.New("managed host requires a non-root memory cgroup membership")
	}
	root = filepath.Clean(root)
	controllers, err := os.ReadFile(filepath.Join(root, "cgroup.controllers"))
	if err != nil {
		return 0, fmt.Errorf("read root cgroup controllers: %w", err)
	}
	if !slices.Contains(strings.Fields(string(controllers)), "memory") {
		return 0, errors.New("root cgroup lacks memory controller")
	}
	path := filepath.Join(root, strings.TrimPrefix(relative, "/"))
	limit := uint64(math.MaxUint64)
	for {
		data, err := os.ReadFile(filepath.Join(path, "memory.max"))
		if err != nil && (path != root || !errors.Is(err, os.ErrNotExist)) {
			return 0, fmt.Errorf("read ancestor memory.max: %w", err)
		}
		if err == nil {
			value := strings.TrimSpace(string(data))
			if value != "max" {
				bytes, err := strconv.ParseUint(value, 10, 64)
				if err != nil {
					return 0, errors.New("invalid ancestor memory.max")
				}
				limit = min(limit, bytes)
			}
		}
		if path == root {
			return limit, nil
		}
		parent := filepath.Dir(path)
		if parent == path || len(parent) < len(root) {
			return 0, errors.New("memory cgroup escaped root")
		}
		path = parent
	}
}

memory_read.text:
func readCgroupMemoryMax(cgroupPath string) (uint64, error) {
	data, err := os.ReadFile(filepath.Join(cgroupPath, "memory.max"))
	if err != nil {
		return 0, err
	}
	value := strings.TrimSpace(string(data))
	if value == "max" {
		return 0, nil
	}
	limit, err := strconv.ParseUint(value, 10, 64)
	if err != nil {
		return 0, errors.New("invalid role memory.max readback")
	}
	return limit, nil
}

reserve_guard.text:
func (a *Agent) reconcileManaged(ctx context.Context, d Desired, target desiredReply,
	backupPending bool,
) (resultErr error) {
	// Load telemetry belongs to the process this pass verifies: forget the
	// previous block now, so a member this pass stops, fails or replaces
	// never keeps publishing its predecessor's load. A successful status
	// report records the new block.
	a.noteTerraBaseLoad(d.Role, nil)
	defer func() {
		if resultErr != nil {
			resultErr = errors.Join(resultErr, a.stopManagedNativeRoot(d.Role))
		}
	}()
	launch := d.ManagedMember
	current, err := a.runner.Observe(ctx, d.Role)
	if err != nil {
		return errors.Join(err, a.runner.Stop(ctx, d.Role))
	}
	if current.Running && current.CgroupMemoryMaxBytes != launch.CgroupMemoryMaxBytes {
		return errors.Join(errors.New("managed role memory.max drifted from desired cap"), a.runner.Stop(ctx, d.Role))
	}
	if launch.Runtime == nil || a.cfg.ManagedRuntimeRoot == "" {
		return errors.Join(errors.New("managed member launch awaits verified mount, artifact, authority material and member identity"), a.runner.Stop(ctx, d.Role))
	}
	if target.Registration == nil || target.Registration.SystemReserveBytes <= 0 ||
		a.cfg.BakedSystemReserveBytes == 0 ||
		launch.SystemReserveBytes != a.cfg.BakedSystemReserveBytes ||
		uint64(target.Registration.SystemReserveBytes) != a.cfg.BakedSystemReserveBytes {
		return errors.Join(errors.New("managed system reserve differs from image priority profile"), a.runner.Stop(ctx, d.Role))
	}
	check := a.memoryCheck
	if check == nil {
		check = validateManagedHostMemory
	}
	if err := check(*target.Registration); err != nil {
		return errors.Join(err, a.runner.Stop(ctx, d.Role))
	}

native_stop.text:
func (a *Agent) stopManagedNativeRoot(role string) error {
	a.nativeRootMu.Lock()
	root := a.nativeRoots[role]
	delete(a.nativeRoots, role)
	a.nativeRootMu.Unlock()
	if root == nil {
		return nil
	}
	root.cancel()
	_ = root.listener.Close()
	<-root.done
	return removeManagedNativeRootSocket(root)
}

reply_binding.text:
func sameDesiredReplyBinding(first, latest desiredReply) bool {
	return first.Desired != nil && latest.Desired != nil && first.Registration != nil && latest.Registration != nil &&
		first.Revision == latest.Revision && first.RegistrationRevision == latest.RegistrationRevision &&
		sameJSON(*first.Registration, *latest.Registration) && sameJSON(*first.Desired, *latest.Desired)
}

func (a *Agent) validateDesiredReply(reply desiredReply) error {
	if len(a.cfg.Identity) != ed25519.PrivateKeySize {
		return errors.New("agent host identity key is invalid")
	}
	a.mu.RLock()
	generation := a.session.RegistrationGeneration
	a.mu.RUnlock()
	if reply.Registration == nil || reply.RegistrationRevision == 0 ||
		reply.Registration.Generation != generation ||
		reply.Registration.Cell != a.cfg.Cell || reply.Registration.Node != a.cfg.Node ||
		reply.Registration.Environment != a.cfg.Environment ||
		reply.Registration.PublicKey != base64.StdEncoding.EncodeToString(a.cfg.Identity.Public().(ed25519.PublicKey)) {
		return errors.New("desired reply registration differs from host session")
	}
	return validateRegistration(*reply.Registration, a.cfg.Cell)
}

desired_validation.text:
func validateDesired(d Desired, cell string, r Registration) error {
	if d.Cell != cell || d.Node != r.Node || d.Environment != r.Environment {
		return errors.New("desired identity mismatch")
	}
	if err := validateToken(d.Role, "role"); err != nil {
		return err
	}
	if !slices.Contains(r.Roles, d.Role) {
		return errors.New("role is not registered")
	}
	if (r.ManagedOCI == nil) != (d.ManagedMember == nil) {
		return errors.New("managed desired and registration kind differ")
	}
	if d.ManagedMember != nil {
		if r.ManagedMember == nil {
			return errors.New("managed registration lacks member binding")
		}
		if d.Role != "terrabase" || *r.ManagedOCI != d.ManagedMember.OCI ||
			*r.ManagedMember != d.ManagedMember.Member {
			return errors.New("managed desired binding differs from registration")
		}
		if err := validateManagedMemberLaunch(*d.ManagedMember, d, r); err != nil {
			return err
		}
	}
	if d.Generation == 0 {
		return errors.New("desired generation must be positive")
	}
	if d.Withdrawn {
		if d.Digest != "" || len(d.Args) != 0 || len(d.Env) != 0 || len(d.Secrets) != 0 {
			return errors.New("withdrawn desired contains execution data")
		}
	} else if err := validateDigest(d.Digest); err != nil {
		return err
	}
	if len(d.Args) > 64 || len(d.Env) > 64 {
		return errors.New("too many workload arguments or environment variables")
	}
	for _, arg := range d.Args {
		if len(arg) > 4096 {
			return errors.New("argument too long")
		}
	}
	for key, value := range d.Env {
		if !regexp.MustCompile(`^[A-Za-z_][A-Za-z0-9_]*$`).MatchString(key) || len(value) > 4096 {
			return errors.New("invalid workload environment")
		}
	}
	// A C# TerraBase member's environment is host-owned: it takes only
	// secret files, whose paths the host sets.
	for key := range d.Secrets {
		if d.Role == terrabase.Role && !vaultsecret.FileKey(key) {
			return errors.New("terrabase takes only Vault secret files (keys ending in _FILE)")
		}
		if roleidentity.Reserved(d.Role, key) {
			return fmt.Errorf("the host sets %s for %s's NATS identity", key, d.Role)
		}
	}
	for key := range d.Env {
		if roleidentity.Reserved(d.Role, key) {
			return fmt.Errorf("the host sets %s for %s's NATS identity", key, d.Role)
		}
	}
	return vaultsecret.ValidateRefs(d.Cell, d.Role, d.Secrets, d.Env)
}

func validateManagedMemberLaunch(launch ManagedMemberLaunch, d Desired, r Registration) error {
	if len(d.Args) != 0 || len(d.Env) != 0 || len(d.Secrets) != 0 {
		return errors.New("managed desired cannot carry arbitrary arguments or environment")
	}
	if validateDigest(launch.SourceDigest) != nil ||
		!strings.HasPrefix(launch.VolumeID, "ocid1.volume.") ||
		!strings.HasPrefix(launch.AttachmentID, "ocid1.volumeattachment.") ||
		len(launch.VolumeID) > 255 || len(launch.AttachmentID) > 255 ||
		strings.ContainsFunc(launch.VolumeID, unicode.IsSpace) || strings.ContainsFunc(launch.AttachmentID, unicode.IsSpace) ||
		launch.Authority.Epoch == 0 ||
		!lowerHex(launch.Authority.ConfigurationID, 64) ||
		!lowerHex(launch.Authority.CertificateSHA256, 64) ||
		!lowerHex(launch.Authority.TLSLeafSHA256, 64) {
		return errors.New("managed launch source, volume or authority is invalid")
	}
	if d.Withdrawn {
		if launch.ProcessMemoryBytes != 0 || launch.MemoryHeadroomBytes != 0 || launch.CgroupMemoryMaxBytes != 0 || launch.SystemReserveBytes != 0 || launch.Runtime != nil {
			return errors.New("withdrawn managed desired contains memory execution data")
		}
		return nil
	}
	const gib = uint64(1 << 30)
	p, h, c := launch.ProcessMemoryBytes, launch.MemoryHeadroomBytes, launch.CgroupMemoryMaxBytes
	if p < 4*gib || h < max(gib, p/4) || h >= p || launch.SystemReserveBytes == 0 ||
		launch.SystemReserveBytes > math.MaxInt64 || launch.SystemReserveBytes != uint64(r.SystemReserveBytes) ||
		validateCgroupMemoryMax(c) != nil || c < p || c > uint64(r.Capacity.MemoryBytes) ||
		p > math.MaxInt64 || h > math.MaxInt64 || p%uint64(os.Getpagesize()) != 0 || h%uint64(os.Getpagesize()) != 0 {
		return errors.New("managed process memory, headroom or cgroup cap is invalid")
	}
	if launch.Runtime != nil {
		if launch.AttachmentETag == "" {
			return errors.New("managed runtime requires an exact attachment ETag")
		}
		if err := validateManagedRuntimePins(*launch.Runtime); err != nil {
			return err
		}
	}
	return nil
}

runtime_pins.text:
func validateManagedRuntimePins(pins ManagedRuntimePins) error {
	if !strings.HasPrefix(pins.DevicePath, "/dev/") || filepath.Clean(pins.DevicePath) != pins.DevicePath ||
		!filepath.IsAbs(pins.MountPath) || filepath.Clean(pins.MountPath) != pins.MountPath ||
		!filesystemUUIDPattern.MatchString(pins.FileSystemUUID) ||
		pins.FileSystemType != "ext4" && pins.FileSystemType != "xfs" ||
		!lowerHex(pins.TrustedKeySHA256, 64) || !lowerHex(pins.ServerCertificateSHA256, 64) ||
		!lowerHex(pins.ServerPrivateKeySHA256, 64) || !lowerHex(pins.ClientCARootsSHA256, 64) ||
		!lowerHex(pins.ClientManagedMaterialManifestSHA256, 64) ||
		!lowerHex(pins.LiveS3ConfigSHA256, 64) || !lowerHex(pins.LiveS3TargetSHA256, 64) ||
		pins.SQLSchemaBundleSHA256 != "" && !lowerHex(pins.SQLSchemaBundleSHA256, 64) ||
		pins.LiveS3Credential.Validate() != nil ||
		!validPrivateIPv4Endpoint(pins.ReplicationListenAddress) {
		return errors.New("managed runtime device, filesystem, material or listener pin is invalid")
	}
	peer := pins.ReplicationPeerMemberID != "" || pins.ReplicationPeerAddress != "" || pins.ReplicationServerCASHA256 != ""
	if !peer || !canonicalMemberID(pins.ReplicationPeerMemberID) || !validPrivateIPv4Endpoint(pins.ReplicationPeerAddress) ||
		!lowerHex(pins.ReplicationServerCASHA256, 64) {
		return errors.New("managed runtime outbound peer pins are incomplete")
	}
	if pins.BackupManifestSHA256 != "" {
		if !lowerHex(pins.BackupManifestSHA256, 64) || !lowerHex(pins.BackupS3ConfigSHA256, 64) ||
			!lowerHex(pins.BackupS3TargetSHA256, 64) || !lowerHex(pins.BackupS3CredentialSHA256, 64) ||
			!lowerHex(pins.BackupDataKeySHA256, 64) || pins.BackupS3TargetSHA256 == pins.LiveS3TargetSHA256 ||
			pins.BackupOwner && (pins.BackupS3Credential.Validate() != nil || pins.BackupDataKey.Validate() != nil ||
				pins.BackupS3Credential.SecretOCID == pins.LiveS3Credential.SecretOCID ||
				pins.BackupS3Credential.SecretOCID == pins.BackupDataKey.SecretOCID) ||
			!pins.BackupOwner && (pins.BackupS3Credential != (oci.SecretVersionReference{}) ||
				pins.BackupDataKey != (oci.SecretVersionReference{})) {
			return errors.New("managed backup runtime pins are incomplete")
		}
	} else if pins.BackupS3ConfigSHA256 != "" || pins.BackupS3TargetSHA256 != "" ||
		pins.BackupS3CredentialSHA256 != "" || pins.BackupDataKeySHA256 != "" || pins.BackupOwner ||
		pins.BackupS3Credential != (oci.SecretVersionReference{}) || pins.BackupDataKey != (oci.SecretVersionReference{}) {
		return errors.New("partial managed backup runtime pins")
	}
	return nil
}

func validPrivateIPv4Endpoint(address string) bool {
	endpoint, err := netip.ParseAddrPort(address)
	return err == nil && endpoint.String() == address && endpoint.Port() != 0 &&
		endpoint.Addr().Is4() && endpoint.Addr().IsPrivate()
}

journal_decode.text:
func DecodeJournal(line []byte) (Entry, bool) {
	var raw struct {
		Unit     string          `json:"_SYSTEMD_UNIT"`
		Comm     string          `json:"_COMM"`
		PID      string          `json:"_PID"`
		Priority string          `json:"PRIORITY"`
		Realtime string          `json:"__REALTIME_TIMESTAMP"`
		Message  json.RawMessage `json:"MESSAGE"`
	}
	if json.Unmarshal(line, &raw) != nil {
		return Entry{}, false
	}
	var message string
	if json.Unmarshal(raw.Message, &message) != nil {
		return Entry{}, false
	}
	entry := Entry{Unit: raw.Unit, Comm: raw.Comm, PID: raw.PID, Message: message, Priority: raw.Priority}
	if micros, err := strconv.ParseInt(raw.Realtime, 10, 64); err == nil {
		entry.At = time.UnixMicro(micros)
	}
	return entry, true
}

log_parser.text:
func (p *Parser) Parse(e Entry) (Record, bool) {
	p.queue = append(p.queue, p.step(e)...)
	if len(p.queue) == 0 {
		return Record{}, false
	}
	r := p.queue[0]
	p.queue = p.queue[1:]
	return r, true
}

// Flush returns the queued records and the headers whose message never came.
func (p *Parser) Flush() []Record {
	out := p.queue
	p.queue = nil
	for pid, head := range p.held {
		out = append(out, head)
		delete(p.held, pid)
	}
	return out
}

func (p *Parser) step(e Entry) []Record {
	var out []Record
	indented := strings.HasPrefix(e.Message, " ")
	if head, ok := p.held[e.PID]; ok {
		delete(p.held, e.PID)
		if indented {
			if p.inRecord == nil {
				p.inRecord = make(map[string]bool)
			}
			p.inRecord[e.PID] = true
			head.Message, head.Example = Normalize(e.Message), example(e.Message)
			return []Record{head}
		}
		out = append(out, head)
	}
	// Exception text and stack frames are indented too; they end with the record.
	if indented && p.inRecord[e.PID] {
		return out
	}
	delete(p.inRecord, e.PID)
	if head, ok := dotnetHeader(e); ok {
		if p.held == nil {
			p.held = make(map[string]Record)
		}
		p.held[e.PID] = head
		return out
	}
	if r, ok := Classify(e); ok {
		out = append(out, r)
	}
	return out
}

// Classify classifies an entry that is a whole record by itself. Any other
// line is a record too, at the level its journal PRIORITY gives.
func Classify(e Entry) (Record, bool) {
	if strings.TrimSpace(e.Message) == "" {
		return Record{}, false
	}
	for _, classify := range []func(Entry) (Record, bool){slogRecord, natsRecord, netbirdRecord} {
		if r, ok := classify(e); ok {
			return r, true
		}
	}
	return Record{Service: unitService(e), Level: priorityLevel(e.Priority), Message: Normalize(e.Message), Example: example(e.Message)}, true
}

// slogRecord reads record v1 and slog JSON: {"level","msg","component","error","service"}.
func slogRecord(e Entry) (Record, bool) {
	var slog struct {
		Level     string `json:"level"`
		Msg       string `json:"msg"`
		Component string `json:"component"`
		Error     string `json:"error"`
		Service   string `json:"service"`
	}
	if !strings.HasPrefix(e.Message, "{") || json.Unmarshal([]byte(e.Message), &slog) != nil || !validLevel(slog.Level) {
		return Record{}, false
	}
	message := slog.Msg
	if slog.Error != "" {
		message += ": " + slog.Error
	}
	return Record{Service: cmp.Or(slog.Service, unitService(e)), Level: slog.Level, Component: slog.Component,
		Message: Normalize(message), Example: example(e.Message)}, true
}

var (
	dotnetHeaderLine = regexp.MustCompile(`^(trce|dbug|info|warn|fail|crit): ([^\[ ]+)`)
	dotnetLevels     = map[string]string{"trce": LevelDebug, "dbug": LevelDebug, "info": LevelInfo, "warn": LevelWarn, "fail": LevelError, "crit": LevelError}
)

// dotnetHeader reads a .NET console header; its message follows on a later line.
func dotnetHeader(e Entry) (Record, bool) {
	m := dotnetHeaderLine.FindStringSubmatch(e.Message)
	if m == nil {
		return Record{}, false
	}
	return Record{Service: commService(e), Level: dotnetLevels[m[1]], Component: m[2]}, true

log_counter.text:
func NewCounter(region, node string) *Counter {
	return &Counter{region: region, node: node, boot: entityid.New(), classes: make(map[Class]tally)}
}

// Add counts one record in the minute being counted. A class keeps the example of its first record.
func (c *Counter) Add(r Record) {
	key := Class{Service: r.Service, Level: r.Level, Component: r.Component, Message: r.Message}
	t, seen := c.classes[key]
	if !seen {
		t.example = r.Example
	}
	t.count++
	c.classes[key] = t
}

// Flush ends a minute and returns its window. The window keeps the most frequent
// classes and counts the rest as dropped; the counter starts the next minute empty.
func (c *Counter) Flush(minute time.Time) Window {
	classes := make([]Class, 0, len(c.classes))
	for key, t := range c.classes {
		key.Count, key.Example = t.count, t.example
		classes = append(classes, key)
	}
	clear(c.classes)
	slices.SortFunc(classes, compareClasses)
	window := Window{Version: 1, Region: c.region, Node: c.node, Minute: minute.UTC(), Boot: c.boot, Seq: c.seq, Classes: classes}
	c.seq++
	if len(classes) > maxClasses {
		window.Dropped = sumCounts(classes[maxClasses:])
		window.Classes = classes[:maxClasses]
	}
	for encodedLen(window) > maxWindowBytes {
		last := len(window.Classes) - 1
		window.Dropped += window.Classes[last].Count
		window.Classes = window.Classes[:last]
	}
	return window
}

// compareClasses puts the most frequent first. Ties go to the more severe level, then to text.
func compareClasses(a, b Class) int {
	return cmp.Or(cmp.Compare(b.Count, a.Count), cmp.Compare(severity(b.Level), severity(a.Level)),
		cmp.Compare(a.Service, b.Service), cmp.Compare(a.Component, b.Component), cmp.Compare(a.Message, b.Message))
}

func sumCounts(classes []Class) int {
	total := 0
	for _, class := range classes {
		total += class.Count
	}
	return total
}

// encodedLen is the window's JSON size. Marshal cannot fail: every field is a string or a number.
func encodedLen(window Window) int {
	data, _ := json.Marshal(window)
	return len(data)
}
